    ) as rows(puzzle_id, player_a, player_b, rule, old_min_steps, old_hint, min_steps, hint)
  loop
    if desired.rule = 'classic' then
      update public.transfer_path_puzzles p set min_steps = desired.min_steps, hint = desired.hint
      where p.puzzle_id = desired.puzzle_id and p.player_a = desired.player_a and p.player_b = desired.player_b
        and p.min_steps is not distinct from desired.old_min_steps and p.hint is not distinct from desired.old_hint;
    elsif desired.rule = 'europe' then
      update public.transfer_path_puzzles p set europe_min_steps = desired.min_steps, europe_hint = desired.hint
      where p.puzzle_id = desired.puzzle_id and p.player_a = desired.player_a and p.player_b = desired.player_b
        and p.europe_min_steps is not distinct from desired.old_min_steps and p.europe_hint is not distinct from desired.old_hint;
    elsif desired.rule = 'active' then
      update public.transfer_path_puzzles p set active_min_steps = desired.min_steps, active_hint = desired.hint
      where p.puzzle_id = desired.puzzle_id and p.player_a = desired.player_a and p.player_b = desired.player_b
        and p.active_min_steps is not distinct from desired.old_min_steps and p.active_hint is not distinct from desired.old_hint;
    else
      raise exception 'unknown Transfer Path rule %', desired.rule;
    end if;
    get diagnostics updated_this_row = row_count;
    if updated_this_row <> 1 then raise exception 'Transfer Path % under %: expected one row carrying %, updated %', desired.puzzle_id, desired.rule, desired.old_min_steps, updated_this_row; end if;
    updated_rows := updated_rows + 1;
  end loop;
  if updated_rows <> 192 then raise exception 'expected to rewrite 192 Transfer Path entries, rewrote %', updated_rows; end if;
  select count(*) into n from public.transfer_path_puzzles where active_min_steps is not null and active_hint is not null;
  if n <> 221 then raise exception 'expected 221 active entries after this migration, found %', n; end if;
  select count(*) into n from public.transfer_path_puzzles;
  if n <> 885 then raise exception 'expected 885 Transfer Path puzzles after this migration, found %', n; end if;
end
